function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // dog
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // trick learning
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20*Math.sin(t), H/2 - 20, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 50 + 20*Math.sin(t), H/2 - 20);
  ctx.stroke();

  // age lines
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.moveTo(W/2 - 20, H/2 + 20 + i*10);
    ctx.lineTo(W/2 + 20, H/2 + 20 + i*10);
    ctx.stroke();
  }

  ctx.restore();
}
